-- Run on a follower to see how far behind it is
SELECT now() - pg_last_xact_replay_timestamp() AS replica_lag;
-- lag > 0 means this follower may still return the pre-write value

-- Cassandra: N=3 replicas, ask for quorum on both sides
CONSISTENCY QUORUM;
INSERT INTO users (id, name) VALUES (42, 'Ada');
SELECT * FROM users WHERE id = 42;
-- QUORUM on N=3 means W=2 and R=2, so W+R(4) > N(3)
